const flashcardsTO: { cat: string; q: string; a: string }[] = [{"cat": "Fundamentos de processos", "q": "Quando a acumulação pode ser eliminada?", "a": "Quando o sistema está em regime permanente em relação à grandeza balanceada."}, {"cat": "Fundamentos de processos", "q": "Por que se usa entalpia em sistemas abertos?", "a": "Porque ela inclui a energia interna e o trabalho de escoamento associado à entrada e à saída de massa."}, {"cat": "Fundamentos de processos", "q": "Qual a relação entre os fatores de Darcy e Fanning?", "a": "O fator de Darcy é quatro vezes o fator de Fanning."}, {"cat": "Fundamentos de processos", "q": "Por que a incrustação reduz a troca térmica?", "a": "Ela acrescenta resistência térmica e diminui o coeficiente global de transferência de calor."}, {"cat": "Fundamentos de processos", "q": "Fluxo difusivo e fluxo total são sempre iguais?", "a": "Não. O fluxo total inclui também a contribuição convectiva."}, {"cat": "Fundamentos de processos", "q": "O que acontece com a carga térmica quando o refluxo aumenta?", "a": "Em geral aumenta, pois mais líquido e vapor circulam internamente na coluna."}, {"cat": "Fundamentos de processos", "q": "Onde se avalia a velocidade no balanço de um CSTR?", "a": "Nas condições de concentração e temperatura da saída, iguais às do tanque idealmente misturado."}, {"cat": "Fundamentos de processos", "q": "Qual ação pode eliminar o erro permanente em uma malha estável?", "a": "A ação integral, desde que o problema e as limitações do atuador permitam atingir a referência."}, {"cat": "Fundamentos de processos", "q": "Qual condição permite iniciar a bisseção?", "a": "Continuidade no intervalo e valores de função de sinais opostos nas extremidades."}, {"cat": "Fundamentos de processos", "q": "Quando Monod prevê metade de μmax?", "a": "Quando a concentração de substrato é igual a KS."}, {"cat": "Fundamentos de processos", "q": "Diluir um efluente remove carga poluidora?", "a": "Não. Sem transformação ou separação, a massa de poluente permanece."}, {"cat": "Fundamentos de processos", "q": "Por que fazer análise de sensibilidade?", "a": "Para identificar quais premissas mais alteram os resultados e a viabilidade do projeto."}, {"cat": "Fundamentos matemáticos", "q": "Por que a unidade de dQ/dt difere de Q?", "a": "Porque uma derivada em relação ao tempo expressa variação da grandeza por unidade de tempo."}, {"cat": "Fundamentos matemáticos", "q": "Qual informação é indispensável para determinar a solução particular de uma EDO de primeira ordem?", "a": "Uma condição inicial ou condição equivalente e os parâmetros do modelo."}, {"cat": "Ciências básicas", "q": "Por que dobrar a velocidade quadruplica a energia cinética para a mesma massa?", "a": "Porque a energia cinética é proporcional ao quadrado da velocidade."}, {"cat": "Ciências básicas", "q": "Se uma resistência permanece constante, o que ocorre com a potência quando se dobra a tensão?", "a": "A potência aumenta quatro vezes, pois P=V²/R."}, {"cat": "Química fundamental", "q": "Como identificar reagente limitante?", "a": "Compare a quantidade disponível de cada reagente dividida pelo respectivo coeficiente estequiométrico."}, {"cat": "Química fundamental", "q": "O que diferencia uma conversão alta de uma seletividade alta?", "a": "Conversão indica reagente consumido; seletividade indica quanto desse consumo gerou o produto desejado."}, {"cat": "Química fundamental", "q": "Equilíbrio químico significa necessariamente que a velocidade de reação seja nula?", "a": "Não. No equilíbrio dinâmico, as velocidades direta e inversa podem ser iguais e não nulas."}, {"cat": "Química fundamental", "q": "Por que o padrão interno ajuda em determinados métodos?", "a": "Ele corrige parte das variações de injeção, preparo ou resposta quando acompanha o analito de maneira adequada."}, {"cat": "Fundamentos matemáticos", "q": "Por que randomizar a ordem dos ensaios?", "a": "Para reduzir a confusão de efeitos de tratamento com tendências de tempo e fatores não controlados."}, {"cat": "Fundamentos matemáticos", "q": "O que sugere determinante zero em uma matriz quadrada de coeficientes?", "a": "A matriz é singular; o sistema não pode ter solução única com aqueles coeficientes."}, {"cat": "Fundamentos matemáticos", "q": "Por que testar o fechamento de massa após uma simulação numérica?", "a": "Para detectar soluções numericamente aceitas que violam uma restrição física de conservação."}, {"cat": "Fundamentos matemáticos", "q": "Qual é a principal diferença entre PFD e P&ID?", "a": "O PFD prioriza a visão de processo; o P&ID detalha tubulações, válvulas e instrumentação."}, {"cat": "Química e materiais", "q": "Por que a presença de cloretos pode agravar a corrosão localizada de algumas ligas?", "a": "Porque pode comprometer filmes passivos em condições suscetíveis, favorecendo ataque localizado."}, {"cat": "Operações e transformações", "q": "Qual informação adicional ao balanço material é necessária para um flash?", "a": "Relações termodinâmicas de equilíbrio entre as fases, válidas para a mistura."}, {"cat": "Operações e transformações", "q": "Por que um balanço de espécie inclui geração e consumo?", "a": "Porque a reação transforma componentes, embora preserve a massa total do sistema fechado à matéria."}, {"cat": "Fenômenos de transporte", "q": "Qual o significado físico da condição de não deslizamento?", "a": "A velocidade do fluido junto à superfície coincide com a velocidade dessa superfície nas condições em que a hipótese é válida."}, {"cat": "Operações e transformações", "q": "Por que o tempo de filtração pode aumentar à medida que a torta cresce?", "a": "Porque a resistência hidráulica adicional da torta reduz vazão a pressão mantida."}, {"cat": "Operações e transformações", "q": "Por que número de estágios teóricos difere de número de pratos instalados?", "a": "Porque contatos reais não atingem, em geral, o equilíbrio perfeito assumido no estágio teórico."}, {"cat": "Operações e transformações", "q": "Por que a extração pode ser vantajosa em separações difíceis por destilação?", "a": "Porque um solvente pode fornecer seletividade mesmo quando volatilidades relativas são insuficientes."}, {"cat": "Operações e transformações", "q": "Por que se usa massa de ar seco como base em muitos cálculos psicrométricos?", "a": "Porque a quantidade de ar seco costuma conservar-se enquanto a quantidade de vapor varia."}, {"cat": "Operações e transformações", "q": "Por que semear uma solução supersaturada?", "a": "Para oferecer superfícies e controlar parte da nucleação e da distribuição de cristais."}, {"cat": "Operações e transformações", "q": "O que indica fator de efetividade menor que um sob hipóteses usuais?", "a": "Que a velocidade média no interior é inferior à que ocorreria sem limitações internas nas condições de superfície."}, {"cat": "Operações e transformações", "q": "Por que considerar limites físicos dos atuadores no controle preditivo?", "a": "Porque a solução do controle deve ser implementável sem exigir movimentos ou valores além da capacidade dos equipamentos."}, {"cat": "Operações e transformações", "q": "Por que o sinal 4 mA pode ser vantajoso em relação a 0 mA em uma malha de corrente?", "a": "Porque permite alimentação e diagnósticos de certas falhas, dependendo do sistema."}, {"cat": "Projeto e sustentabilidade", "q": "Por que um material aprovado em um meio pode falhar em outro?", "a": "Porque mecanismo e intensidade de degradação dependem de composição, temperatura, contaminantes e condições de operação."}, {"cat": "Projeto e sustentabilidade", "q": "Por que a conversão precisa ser alta para obter cadeias longas no crescimento por etapas ideal?", "a": "Porque o comprimento médio aumenta muito apenas quando a maioria dos grupos reativos já reagiu."}, {"cat": "Projeto e sustentabilidade", "q": "Como a eficiência de corrente altera a produção prevista por Faraday?", "a": "Multiplica a quantidade teórica pela fração de corrente destinada à reação de interesse."}, {"cat": "Bioprocessos e ambiente", "q": "Quando ocorre limitação de oxigênio em um cultivo aeróbio?", "a": "Quando a demanda de oxigênio das células ultrapassa a capacidade efetiva de transferência ao meio."}, {"cat": "Bioprocessos e ambiente", "q": "Por que vazão é indispensável para quantificar a remoção de carga?", "a": "Porque carga é quantidade de poluente por unidade de tempo, obtida por concentração vezes vazão."}, {"cat": "Projeto e sustentabilidade", "q": "O que representa o ΔTmin no método pinch?", "a": "A diferença mínima admissível entre correntes quentes e frias, usada para estabelecer metas de recuperação de calor."}, {"cat": "Projeto e sustentabilidade", "q": "Por que uma área térmica calculada não encerra o dimensionamento de trocador?", "a": "Porque perdas de pressão, escoamento, incrustação, vibração e fabricação também restringem o projeto."}, {"cat": "Projeto e sustentabilidade", "q": "Qual é o propósito de examinar desvios em um HAZOP?", "a": "Identificar causas, consequências e salvaguardas de condições de processo diferentes das pretendidas."}, {"cat": "Projeto e sustentabilidade", "q": "Qual é a diferença entre limite de controle e limite de especificação?", "a": "O primeiro vem do comportamento estatístico observado do processo; o segundo expressa requisito de produto ou desempenho."}, {"cat": "Projeto e sustentabilidade", "q": "Por que o payback simples não substitui VPL?", "a": "Porque não considera corretamente o valor temporal do dinheiro nem todos os fluxos relevantes."}, {"cat": "Projeto e sustentabilidade", "q": "Por que comparar simulação com um balanço independente?", "a": "Para identificar inconsistências de modelagem que o algoritmo de solução pode não detectar."}, {"cat": "Projeto e sustentabilidade", "q": "Por que a unidade funcional é central em uma ACV?", "a": "Porque define o serviço ou resultado equivalente que permite comparar diferentes sistemas de produto."}, {"cat": "Fundamentos de processos", "q": "Um evaporador recebe 240 kg/h a 10% de sólido não volátil e entrega concentrado a 30%. Qual é a vazão evaporada?", "a": "Entram 24 kg/h de sólido. Como não evapora sólido, o concentrado é 24/0,30=80 kg/h. Pelo balanço global, evaporam 160 kg/h. A água passa de 216 kg/h na entrada para 56 kg/h no concentrado e 160 kg/h no vapor."}, {"cat": "Fundamentos de processos", "q": "Um aquecedor sem perdas eleva 3 kg/s de água de 25 a 45 °C, com cp=4,2 kJ/(kg·K). Qual a carga térmica?", "a": "Com variações cinética e potencial desprezíveis e cp constante, Q̇=ṁcpΔT=3×4,2×20=252 kW. O valor é positivo para calor fornecido ao fluido e não inclui mudança de fase."}, {"cat": "Fundamentos de processos", "q": "Um tubo tem L=20 m, D=0,05 m, v=2 m/s e f_D=0,02. Qual a perda distribuída de carga?", "a": "h_f=f_D(L/D)v²/(2g)=0,02×400×4/(19,62)≈1,63 m de fluido, para g=9,81 m/s². Isso não inclui cotas nem perdas localizadas."}, {"cat": "Fundamentos de processos", "q": "Uma parede de 0,20 m² tem h interno=100 e externo=50 W/(m²·K), sem resistência de parede. Qual U na mesma área?", "a": "Como resistências convectivas estão em série, 1/U=1/100+1/50=0,03 m²K/W e U≈33,3 W/(m²·K). A condução e incrustação, se presentes, reduzirão U."}, {"cat": "Fundamentos de processos", "q": "Se D_AB=1,5×10⁻⁹ m²/s e dC_A/dz=−2000 mol/m⁴, qual o fluxo difusivo de Fick?", "a": "J_A=−D_AB dC_A/dz=3,0×10⁻⁶ mol/(m²·s), positivo no sentido crescente de z. É um fluxo relativo à referência difusiva adotada, não necessariamente o fluxo molar total."}, {"cat": "Fundamentos de processos", "q": "Uma alimentação de 100 kmol/h tem z_A=0,40; D sai com x_D=0,80 e fundo com x_B=0,10. Qual D?", "a": "Do balanço global B=100−D. Do balanço de A: 40=0,8D+0,1(100−D), logo 30=0,7D e D≈42,86 kmol/h. O fundo é ≈57,14 kmol/h."}, {"cat": "Fundamentos de processos", "q": "Um CSTR isotérmico de primeira ordem recebe 2 L/s, k=0,2 s⁻¹ e precisa atingir X=0,5. Qual V?", "a": "Com densidade constante, V=ν₀ X/[k(1−X)]=2×0,5/(0,2×0,5)=10 L. Uma variação de temperatura alteraria k e exigiria outro balanço."}, {"cat": "Fundamentos de processos", "q": "Para K=3 e τ=4 min, um degrau de entrada de 2 unidades ocorre em t=0. Quanto varia a saída em 4 min?", "a": "A variação final é K×2=6. Após uma constante de tempo, Δy=6(1−e⁻¹)≈3,79 unidades, sem atraso e com modelo de primeira ordem válido."}, {"cat": "Fundamentos de processos", "q": "Para f(x)=x²−9 com x₀=4, qual é o passo de Newton?", "a": "f(4)=7 e f′(4)=8; logo x₁=4−7/8=3,125. A aproximação é coerente com raiz positiva 3, mas novos passos e avaliação do resíduo ainda são necessários."}, {"cat": "Fundamentos de processos", "q": "Se k_La=80 h⁻¹ e C*−C_L=0,003 g/L, qual OTR?", "a": "OTR=k_La ΔC=80×0,003=0,24 g/(L·h). Para 1000 L seriam 240 g/h como estimativa de transferência, antes de variações espaciais e de operação."}, {"cat": "Fundamentos de processos", "q": "A DQO cai de 500 para 100 mg/L mantendo Q=200 m³/d. Quantos kg de DQO são removidos por dia?", "a": "Entrada 200×500×0,001=100 kg/d; saída 200×100×0,001=20 kg/d. Remoção=80 kg/d, eficiência de 80%, assumindo vazões estáveis e representativas."}, {"cat": "Fundamentos de processos", "q": "Um processo dispõe de calor residual de 180 kW durante 4000 h/ano; se toda energia substituísse utilidade de R$ 0,12/kWh, qual economia bruta?", "a": "Energia anual=180×4000=720000 kWh. Economia bruta máxima=R$ 86.400/ano. O cálculo ignora disponibilidade real, eficiência da recuperação, manutenção e CAPEX."}, {"cat": "Fundamentos matemáticos", "q": "Se C(x)=x²−6x+15, para 1≤x≤5, qual o mínimo matemático?", "a": "C′=2x−6 zera em x=3. Como C″=2 positivo, C(3)=6 é o mínimo interno; nos extremos C(1)=10 e C(5)=10. O resultado só tem uso industrial se x e C tiverem significado físico e unidades definidas."}, {"cat": "Fundamentos matemáticos", "q": "Um tanque recebe q(t)=4+t L/min de 0 a 6 min, sem saída. Quanto volume é adicionado?", "a": "Integre de 0 a 6: V=∫(4+t)dt=[4t+t²/2]₀⁶=24+18=42 L. A vazão final é 10 L/min; não multiplique 10 por 6."}, {"cat": "Ciências básicas", "q": "Um corpo de 5 kg passa de 3 para 7 m/s. Qual a variação da energia cinética?", "a": "ΔEc=0,5×5×(49−9)=100 J. Essa é a variação da energia cinética; o trabalho resultante deve igualar 100 J sob o teorema trabalho–energia."}, {"cat": "Ciências básicas", "q": "Um transmissor de 0 a 200 °C fornece 16 mA em escala 4–20 mA. Qual temperatura indicada?", "a": "(16−4)/(20−4)=0,75 da faixa; temperatura ideal indicada=150 °C. A leitura não garante exatidão sem calibração."}, {"cat": "Química fundamental", "q": "Na reação N₂+3H₂→2NH₃, entram 2 mol de N₂ e 3 mol de H₂. Qual produção teórica?", "a": "H₂ limita a extensão a 1 mol de reação; formam-se 2 mol de NH₃ e sobra 1 mol de N₂, para conversão completa do limitante."}];

